WITH EmployeesByDepartment AS (SELECT dept_id, ROUND(AVG(salary), 2) AS avg_salary, ROUND((100 * SUM(CASE WHEN job_title = 'Manager' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_manager FROM employees GROUP BY dept_id) SELECT departments.location, departments.budget, EmployeesByDepartment.avg_salary, EmployeesByDepartment.pct_manager FROM departments LEFT JOIN EmployeesByDepartment ON departments.id = EmployeesByDepartment.dept_id WHERE EmployeesByDepartment.pct_manager >= 73 ORDER BY EmployeesByDepartment.avg_salary DESC;
